violations.content:
style={{
          padding: 'var(--spacing-5)',
          border: 'var(--spacing-0-5) solid hsl(var(--destructive))',
          borderRadius: 'var(--spacing-2)',
          backgroundColor: 'hsl(var(--destructive) / 0.1)',
          color: 'hsl(var(--destructive))',
          margin: 'var(--spacing-2-5)'
        }}

style={{
              padding: 'var(--spacing-2) var(--spacing-4)',
              backgroundColor: 'hsl(var(--primary))',
              color: 'hsl(var(--background))',
              border: 'none',
              borderRadius: 'var(--spacing-1)',
              cursor: 'pointer'
            }}

style={{
                              maxWidth,
                              maxHeight,
                              width: 'auto',
                              height: 'auto',
                              aspectRatio: dimensions.aspectRatio
                            }}

style={{
                maxWidth: 'calc(100vw - var(--spacing-20))',
                maxHeight: 'calc(100vh - 180px)',
                width: 'auto',
                height: 'auto',
                display: 'block',
                objectFit: 'contain',
                boxShadow: '0 25px 50px -var(--spacing-3) hsl(var(--foreground) / 0.5)'
              }}

style={{
              position: 'absolute',
              bottom: 'var(--spacing-4)',
              left: '50%',
              transform: 'translateX(-50%)',
              color: 'rgba(255, 255, 255, 0.8)',
              fontSize: 'var(--spacing-3-5)'
            }}

style={{
          // 🎯 移除冲突的定位样式，让基础Dialog组件和CSS处理定位
          maxHeight: '85vh',
          maxWidth: 'min(95vw, 1024px)', // max-w-4xl = 1024px
          width: 'auto',
          height: 'auto'
        }}

style={{
      background: 'linear-gradient(135deg, hsl(var(--primary)) 0%, hsl(var(--accent)) 100%)',
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
    }}
